using System.Text.Json;
using FaultIQ.Api.Common;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Mvc;

namespace FaultIQ.Api.Features;

// The fault library (ADR 0025). Generated by `python -m faultiq export-library` from the cited
// TOML library plus FaultIQ's held-out diagnosis results, embedded in this assembly, served read-only.

public sealed record CitedText(string Text, string Source);

public sealed record LibrarySource(string Id, string Citation, string? Url);

public sealed record Symptom(string Feature, string Signal, string Unit, string Kind, int DecidingHours);

public sealed record Confusion(string Fault, int NamedAsOtherHours, int OtherNamedAsThisHours);

public sealed record SeverityResult(double Intensity, int Hours, double RightFault, double SaidNoFault, double Inconclusive);

public sealed record FaultPerformance(int TestHours, double Precision, double Recall, IReadOnlyList<SeverityResult> BySeverity);

public sealed record FaultMeasurements(
    string Source, IReadOnlyList<Symptom> Symptoms, IReadOnlyList<Confusion> ConfusedWith, FaultPerformance Performance);

public sealed record LibraryFault(
    string Id, string Title, string Equipment, string Dataset, string DatasetLabel, string IntensityUnit,
    string PlainName, string Component, CitedText? PlainSummary, CitedText? WhatToDo,
    CitedText? Definition, CitedText? Observed, IReadOnlyList<CitedText> Causes, IReadOnlyList<CitedText> Checks,
    FaultMeasurements Measured);

public sealed record FaultLibraryDocument(
    int Version, string ReviewStatus, string DiagnosisVersion, IReadOnlyList<LibrarySource> Sources,
    IReadOnlyList<LibraryFault> Faults);

public sealed record FaultLibraryResponse(
    string ReviewStatus, IReadOnlyList<LibrarySource> Sources, IReadOnlyList<LibraryFault> Items);

public sealed record LibraryFaultResponse(string ReviewStatus, LibraryFault Fault, IReadOnlyList<LibrarySource> Sources);

public sealed class FaultLibraryStore
{
    public FaultLibraryDocument Document { get; }

    public FaultLibraryStore()
    {
        using var stream = typeof(FaultLibraryStore).Assembly.GetManifestResourceStream("FaultIQ.FaultLibrary.json")
            ?? throw new InvalidOperationException("The fault library is not embedded in the API assembly.");
        Document = JsonSerializer.Deserialize<FaultLibraryDocument>(stream,
                       new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower })
                   ?? throw new InvalidOperationException("The fault library is empty.");
    }

    /// <summary>Case-insensitive search over names, equipment, symptoms, causes and observations.</summary>
    public static bool Matches(LibraryFault f, string q) =>
        new[] { f.Id, f.Title, f.PlainName, f.Equipment, f.DatasetLabel, f.Observed?.Text, f.Definition?.Text, f.PlainSummary?.Text }
            .Concat(f.Measured.Symptoms.Select(s => s.Signal))
            .Concat(f.Causes.Select(c => c.Text))
            .Any(t => t?.Contains(q, StringComparison.OrdinalIgnoreCase) == true);
}

public static class FaultLibraryEndpoints
{
    public static RouteGroupBuilder MapFaultLibraryEndpoints(this RouteGroupBuilder api)
    {
        var g = api.MapGroup("/fault-library").WithTags("fault-library");

        g.MapGet("/", (FaultLibraryStore store, [FromQuery] string? q, [FromQuery] string? equipment) =>
        {
            var doc = store.Document;
            var items = doc.Faults.Where(f =>
                (string.IsNullOrWhiteSpace(q) || FaultLibraryStore.Matches(f, q.Trim()))
                && (string.IsNullOrWhiteSpace(equipment) || f.Equipment == equipment)).ToList();
            return TypedResults.Ok(new FaultLibraryResponse(doc.ReviewStatus, doc.Sources, items));
        }).WithName("ListFaultLibrary");

        g.MapGet("/{id}", Results<Ok<LibraryFaultResponse>, ProblemHttpResult> (FaultLibraryStore store, string id) =>
        {
            var doc = store.Document;
            var fault = doc.Faults.FirstOrDefault(f => f.Id == id);
            if (fault is null)
            {
                return Problems.NotFound("Fault");
            }

            var cited = new[] { fault.Definition, fault.Observed, fault.PlainSummary, fault.WhatToDo }.OfType<CitedText>()
                .Concat(fault.Causes).Concat(fault.Checks).Select(c => c.Source)
                .Append(fault.Measured.Source).ToHashSet();
            return TypedResults.Ok(new LibraryFaultResponse(doc.ReviewStatus, fault,
                doc.Sources.Where(s => cited.Contains(s.Id)).ToList()));
        }).WithName("GetFaultLibraryEntry");

        return api;
    }
}
